function applyVocabularyV39(data,book,reference){
 const patch=window.STUDY_VOCABULARY_V39?.[book];if(!patch)return;const words=new Map(data.vocab.map(w=>[w.id,w])),units=new Map();for(const r of data.readings)for(const s of r.sections)for(const u of s.entries)units.set(u.id,u);for(const l of data.lessons)for(const g of l.grammar)for(const u of g.examples)units.set(u.id,u);for(const c of reference?.categories||[])for(const g of c.entries)for(const u of [...(g.examples||[]),...(g.forms||[])])if(!units.has(u.id))units.set(u.id,u);
 for(const original of patch.words){if(words.has(original.id))continue;const w=JSON.parse(JSON.stringify(original));data.vocab.push(w);words.set(w.id,w);data.annotations[w.word]??=w.ruby}
 for(const [id,link]of Object.entries(patch.links)){const w=words.get(id);if(!w)continue;w.lessons=[...new Set([...(w.lessons||[]),...link.lessons])].sort((a,b)=>a-b);if(!w.lesson&&w.lessons.length)w.lesson=w.lessons[0];w.contexts=[...new Map([...(w.contexts||[]),...link.contexts.map(id=>units.get(id)).filter(Boolean)].map(u=>[u.id,u])).values()].slice(0,2)}
}
function applyVocabularyAudioV39(book,audio){const patch=window.STUDY_VOCABULARY_V39?.[book]?.audio;if(!patch||!audio)return;Object.assign(audio.tracks,patch.tracks);Object.assign(audio.clips,patch.clips);for(const w of window.STUDY_VOCABULARY_V39[book].words){const id='word:'+w.id;if(!audio.clips[id])continue;const key=s=>String(s).normalize('NFKC').replace(/[\s、。，,.！？!?「」『』“”‘’（）()・：:；;]/g,'').toLowerCase();audio.byText[key(w.word)]??=id;audio.byText[key(w.kana)]??=id}}
